			title = "林地传说",
			text = [=[• {link:forsaken}被遗忘者{/link}说，{link:deathknell}丧钟镇{/link}的墓穴看守者曾准备将许多新复苏者在醒来之前就焚烧掉。
• 在瘟疫之前，{link:shadowvale}暗影谷{/link}那些离群索居的居民用西部山丘的草药酿造一种绿色药剂。药剂师、神秘主义者和下毒者都在寻求它，即便在首都被禁之后依然如此。]=],
		},
	},
})

Translate("zhCN", "deathknell", {
	title = "丧钟镇",
	sections = {
		{
			title = "概述",
			text = [=[丧钟镇是{link:tirisfal-glades}提瑞斯法{/link}西部的一座亡者小村。它的墓穴坐落在一座山丘上，下方是一座礼拜堂和一片墓地。{link:forsaken}被遗忘者{/link}把他们找到的尸体带到这里，许多人在这里摆脱巫妖王的奴役，重新恢复自我意识。{link:undertaker-mordo}送葬者摩尔多{/link}迎接他们。{link:shadow-priest-sarvis}暗影牧师萨维斯{/link}向他们解释他们变成了什么，{link:executor-arren}执行官阿伦{/link}则给他们分派任务。这座村子并不安全。无意识的亡者在它北面的房屋间游荡，蜘蛛占满了{link:nightbane-worgen}夜行{/link}蜘蛛洞穴的{link:ginro-hearthkindle}金{/link}矿，{link:scarlet-crusade}血色十字军{/link}还在东南方设有一座营地。]=],
		},
	},
})

Translate("zhCN", "brill", {
