	sections = {
		{
			title = "概述",
			text = [=[布瑞尔是{link:forsaken}被遗忘者{/link}在{link:tirisfal-glades}提瑞斯法{/link}的主要城镇，位于{link:deathknell}丧钟镇{/link}与{link:undercity}幽暗城{/link}之间的道路上。它的城镇大厅是{link:magistrate-sevren}执政官塞弗伦{/link}和{link:executor-zygand}执行官塞加德{/link}的驻地，他们指挥着{link:moonglade}林地{/link}的亡灵卫兵。镇上的墓地由初级药剂师照看，而镇上的旅店恐惧之末旅店有一个地窖，被俘的{link:humans}人类{/link}和{link:dwarves}矮人{/link}在那里等待药剂师的实验。在镇子不远处，{link:horde}部落{/link}的飞艇从塔楼上升起；如今，就连一位被遗忘者圣骑士的训练师也在布瑞尔有了一席之地。]=],
		},
	},
