Translate("zhCN", "agamand-mills", {
	title = "阿加曼德磨坊",
	aliases = { "阿加曼德家族墓穴" },
	sections = {
		{
			title = "概述",
			text = [=[阿加曼德磨坊矗立在{link:tirisfal-glades}提瑞斯法{/link}北部的{link:razorfen-downs}高地{/link}上。它们是{link:moonglade}林地{/link}中最富有的家族阿加曼德家的财富。瘟疫来临时，阿加曼德家族加固了宅邸，命令他们的工人留下来战斗。他们全都死了，又全都复起了。如今，这些磨坊是{link:scourge}天灾军团{/link}在提瑞斯法最坚固的据点。磨坊北端是阿加曼德家族墓穴，一个名叫达高尔的骷髅上尉在那里唤醒了这个家族的先人，让他们为巫妖王而战。]=],
		},
	},
})

Translate("zhCN", "solliden-farmstead", {
