	sections = {
		{
			title = "概述",
			text = [=[索利丹农场位于{link:tirisfal-glades}提瑞斯法{/link}西部，{link:deathknell}丧钟镇{/link}以北。它是{link:moonglade}林地{/link}中最后几处仍有活着的{link:humans}人类{/link}耕种田地的地方之一。南瓜仍在生长，农夫们仍在收获，因为{link:scarlet-crusade}血色十字军{/link}在西边的一座塔楼上保护着他们。{link:forsaken}被遗忘者{/link}憎恨这座农场所拥有的生机。尽管如此，{link:brill}布瑞尔{/link}的药剂师们还是为它的南瓜找到了用处。农场西北方的峭壁上矗立着{link:bandarion-keep}班达里昂要塞{/link}。]=],
