Translate("zhCN", "venomweb-vale", {
	title = "毒蛛峡谷",
	sections = {
		{
			title = "概述",
			text = [=[毒蛛峡谷是{link:tirisfal-glades}提瑞斯法{/link}最东部的一片宽阔{link:stranglethorn-vale}山谷{/link}，位于{link:scarlet-monastery}血色修道院{/link}所在的{link:razorfen-downs}高地{/link}之下。它的林间结满了蛛网。在那里筑巢的巨型蜘蛛带有一种毒液，{link:brill}布瑞尔{/link}的药剂师们相信这种毒液曾经保存过一种古老的瘟疫。最近，亡灵卫兵还看到一只失控的憎恶在峡谷附近游荡。这样的怪物本不该神不知鬼不觉地越过{link:the-bulwark}亡灵壁垒{/link}，亡灵卫兵对此事守口如瓶。在峡谷的北缘，{link:scarlet-crusade}血色十字军{/link}设有一座自己的营地。]=],
		},
	},
