Translate("zhCN", "scarlet-watch-post", {
	title = "血色十字军哨岗",
	sections = {
		{
			title = "概述",
			text = [=[血色十字军哨岗是{link:scarlet-crusade}血色十字军{/link}在{link:tirisfal-glades}提瑞斯法{/link}东北部的一座塔楼，位于法奥之墓的另一侧。它监视着通往{link:scarlet-monastery}血色修道院{/link}的北方要道。它的指挥官梅尔拉奇上尉在{link:forsaken}被遗忘者{/link}中以冷酷无情著称，他的两名保镖从不离身。这座塔楼是十字军在{link:moonglade}林地{/link}各处设立的数座塔楼之一。巡逻队从每一座塔楼出发，去焚烧亡者。佩里恩上尉据守着{link:brill}布瑞尔{/link}西南方的一座残塔，瓦逊上尉则据守着东南方{link:barnil-stonepot}巴尼尔{/link}农场附近的另一座。]=],
