Translate("zhCN", "capital-city", {
	title = "洛丹伦王城",
	aliases = { "洛丹伦城" },
	sections = {
		{
			title = "概述",
			text = [=[王城的废墟矗立在{link:tirisfal-glades}提瑞斯法{/link}的东部边缘。数百年来，它一直是{link:lordaeron}洛丹伦{/link}历代国王的驻地。{link:arthas-menethil}阿尔萨斯·米奈希尔{/link}王子正是在这里从诺森德归来，在王座上杀死了他的父亲。城市遭到洗劫，沦为废墟。如今，它残破的城墙和空荡荡的王座大厅守护着通往其下方{link:undercity}幽暗城{/link}的道路，那是{link:forsaken}被遗忘者{/link}的城市。旧日街道的一部分仍不属于他们。{link:scourge}天灾军团{/link}的部队仍在东部废墟中徘徊，被遗忘者正在为夺回它们而战。]=],
		},
	},
})

Translate("zhCN", "whispering-forest", {
