Translate("zhCN", "bandarion-keep", {
	title = "班达里昂要塞",
	aliases = { "北面岩" },
	sections = {
		{
			title = "概述",
			text = [=[班达里昂要塞是{link:forsaken}被遗忘者{/link}圣骑士教团{link:tyr-s-watch}提尔守望{/link}的修道院。它坐落在北面岩上，那是{link:whispering-forest}低语森林{/link}与{link:tirisfal-glades}提瑞斯法{/link}其他地区之间的一道陡峭断崖。在上一场战争中，{link:argent-dawn}银色黎明{/link}曾在这里抵御{link:scourge}天灾军团{/link}。当银色黎明撤往瘟疫之地后，这座要塞便沦为废墟，邪鳍{link:murlocs}鱼人{/link}把它变成了产卵地。{link:danitha-morr}达妮莎·莫尔{/link}和她的圣骑士们赶走了鱼人，开始重建。她以{link:garek-bandarion}加瑞克·班达里昂{/link}的名字为这座要塞命名，他是第一个重新拾起{link:holy-light}圣光{/link}的被遗忘者。]=],
		},
	},
})

Translate("zhCN", "shadowvale", {
	title = "暗影谷",
	sections = {
		{
			title = "概述",
			text = [=[暗影谷是{link:whispering-forest}低语森林{/link}深处的一座废弃村庄，位于{link:bandarion-keep}班达里昂要塞{/link}西南方。村民生前古怪而孤僻，不欢迎外来者。如今，这座村庄属于玷污者，那些复起之后将{link:holy-light}圣光{/link}转而对准自己同胞的圣骑士。无意识的亡者聚集在村子下面的地窖里。据说一名教徒把一块浮空城水晶的碎片带到了那里，不管它起什么作用，它都使亡者变得更强大，或者更多。]=],
		},
	},
})

Translate("zhCN", "tyr-s-watch", {
	title = "提尔守望",
	sections = {
		{
			title = "概述",
			text = [=[提尔守望是一个{link:forsaken}被遗忘者{/link}圣骑士教团，新近成立于{link:tirisfal-glades}提瑞斯法林地{/link}。它的成员生前都是{link:holy-light}圣光{/link}的仆人。他们死去，又复起，发现圣光仍然回应着他们，尽管它的触碰如今会灼烧他们的血肉。他们的修道院设在{link:bandarion-keep}班达里昂要塞{/link}，由{link:danitha-morr}达妮莎·莫尔{/link}领导。]=],
		},
		{
			title = "信仰",
			text = [=[提尔守望的圣骑士教导说，痛苦不是背离{link:holy-light}圣光{/link}的理由。治疗会伤害他们，所以他们学会在痛苦中治疗，并称之为一场熔炼。他们教导说，为了善本身而追求善，是他们使命的核心。他们寻访{link:undercity}幽暗城{/link}中的不幸者和{link:forsaken}被遗忘者{/link}，以微小的方式帮助他们，因为他们相信，微小的善举也能将他们与圣光联系在一起。]=],
		},
		{
			title = "教团与它的人民",
			text = [=[{link:forsaken}被遗忘者{/link}清楚地记得，生者曾以{link:holy-light}圣光{/link}之名对他们做过什么。许多人害怕某一天会有一名圣骑士把他们当作怪物击杀。有些复起的圣骑士正是这么做的。教团称他们为玷污者，并追捕他们。{link:sylvanas-windrunner}黑暗女王{/link}本人也不信任提尔守望，她已告诉教团的圣骑士们，她在注视着他们。{link:danitha-morr}达妮莎{/link}相信，也许需要数年乃至数十年，她的教团才能得到完全的信任。不管怎样，她都要去赢得这份信任。]=],
		},
	},
})

