			text = [=[加瑞克·班达里昂是{link:lordaeron}洛丹伦{/link}的一名士兵，他死于王国的陷落，又在{link:forsaken}被遗忘者{/link}中复起。他成为亡灵卫兵的第一任上尉，也是第一个以圣骑士身份重新拾起{link:holy-light}圣光{/link}的被遗忘者。当浮空城{red:naxxramas}纳克萨玛斯{/red}进攻{link:undercity}幽暗城{/link}时，他倒下了。{link:tyr-s-watch}提尔守望{/link}的圣骑士们以他的名字为他们的修道院命名，至今仍把他的名字当作战吼。]=],
		},
		{
			title = "意义",
			text = [=[对{link:forsaken}被遗忘者{/link}圣骑士而言，加瑞克证明了{link:holy-light}圣光{/link}并未在死亡中抛弃他们。对亡灵卫兵而言，他是建立起他们队伍的上尉。他的一生把生者王国的最后时日与亡者王国的最初时日连在了一起。]=],
		},
		{
			title = "事迹",
			text = [=[• 生前，他在首都的城市卫队中效力，隶属于兰登上尉，兰登选定他作为自己的继任者。
• 在{link:arthas-menethil}阿尔萨斯{/link}弑父的那一天，他和兰登带领幸存者从城市下方的下水道中逃出。
• 他向瑞文戴尔{link:the-baron}男爵{/link}复了仇，正是这位领主将王国出卖给了{link:cult-of-the-damned}诅咒教派{/link}；随后他死于伤势和瘟疫。
• 作为{link:forsaken}被遗忘者{/link}，他在{link:undercity}幽暗城{/link}最初的日子里与{link:dark-ranger-anya}黑暗游侠安雅{/link}并肩作战。
• 他升任亡灵卫兵的上尉。
• 他在保卫幽暗城抵御{link:nak}纳克{/link}萨玛斯的战斗中阵亡。]=],
		},
	},
	chapters = {
		{
			title = "洛丹伦的最后时日",
			hint = "了解幽暗城的被遗忘者如何讲述他们的第一任上尉。",
			text = [=[加瑞克曾是一名渴望战斗的年轻卫兵，他的上尉兰登告诉他，保护百姓才是更大的荣耀。在{link:arthas-menethil}阿尔萨斯{/link}杀死国王{link:terenas-menethil}泰瑞纳斯·米奈希尔{/link}的那一夜，他们发现王座大厅里挤满了教徒。{link:uther-the-lightbringer}光明使者乌瑟尔{/link}派他们去尽可能多地救人。在城市下方，他们发现教派早已做好了准备。兰登留下来拖住瑞文戴尔{link:the-baron}男爵{/link}，好让加瑞克带领百姓脱险。加瑞克从未原谅那位男爵。他一路追到斯坦索姆，在那里杀死了他，而他自己也因伤而死。]=],
		},
		{
			title = "第二次生命",
			hint = "听班达里昂要塞的圣骑士们讲述他们的创始人。",
			text = [=[加瑞克在{link:undercity}幽暗城{/link}的地窖中醒来，除了自己的名字，什么也不记得。药剂师普{link:trey-lightforge}特雷{/link}斯想把他的身体拆作零件。{link:dark-ranger-anya}黑暗游侠安雅{/link}阻止了他。加瑞克宣誓效忠{link:sylvanas-windrunner}希尔瓦娜斯{/link}，与安雅一起从废墟中聚集拥有自由意志的亡者，清理地道，帮助这座城市发展壮大。当{link:scarlet-crusade}血色十字军{/link}攻破幽暗城的城墙时，他率领亡灵卫兵迎击他们。就在那些年间的某个时候，{link:holy-light}圣光{/link}开始再次回应他。]=],
		},
		{
			title = "以他命名的要塞",
			hint = "了解北面岩上的要塞为何以他的名字命名。",
			text = [=[当{link:nak}纳克{/link}萨玛斯来到首都废墟时，{link:forsaken}被遗忘者{/link}与{link:argent-dawn}银色黎明{/link}在地面上并肩与它作战。加瑞克没有回来。{link:danitha-morr}达妮莎·莫尔{/link}和{link:leonid-barthalomew}莱尼德·巴萨罗梅{/link}参加了那场战斗，并在那里失去了许多朋友。当达妮莎为她的教团占据{link:bandarion-keep}北面岩{/link}上的古老要塞时，她以他的名字为它命名。]=],
		},
	},
	mentions = {
		{ text = "正义的事业" },
