	aliases = { "安雅" },
	sections = {
		{
			title = "概述",
			text = [=[安雅是一名黑暗游侠，是侍奉{link:sylvanas-windrunner}希尔瓦娜斯·风行者{/link}的亡灵精灵之一。生前，她是希尔瓦娜斯麾下的一名{link:quel-thalas}奎尔萨拉斯{/link}游侠。她在保卫家园抵御{link:scourge}天灾军团{/link}时死去，并作为它的奴隶复起。她记得自己在那段时间里所做的一切。当她挣脱束缚时，希尔瓦娜斯给了她一个归属之地，为此，安雅向黑暗女王献上了永远的忠诚。]=],
		},
		{
			title = "意义",
			text = [=[安雅是{link:forsaken}被遗忘者{/link}最早的黑暗游侠之一，也是亲眼看着{link:undercity}幽暗城{/link}从地道中崛起的人之一。在亡者王国早期的战争中，她一直是{link:garek-bandarion}加瑞克·班达里昂{/link}的同伴。他失去了记忆，她却保留了自己的全部记忆，她教导他说，对许多被遗忘者而言，死亡是一张白纸，是第二次生命。她很少信任生者。当一名昔日白银之手的圣骑士对一名被遗忘者劳工表示怜悯、而他的上尉却依然杀死了那个人时，安雅告诉加瑞克，生者永远不会把亡灵当作人来看待，他们是不可信任的。]=],
		},
		{
			title = "事迹",
			text = [=[• 她在保卫{link:quel-thalas}奎尔萨拉斯{/link}时倒下，作为巫妖王的奴隶做过可怕的事情。
• 当{link:garek-bandarion}加瑞克{/link}醒来时，她阻止了药剂师普{link:trey-lightforge}特雷{/link}斯把他拆作零件。
• 她告诉加瑞克，失去记忆是一种仁慈，因为她对自己的罪行记得太清楚了。
• 她与加瑞克一起从首都废墟中解救拥有自由意志的亡者。
• 她与他并肩对抗{link:scarlet-crusade}血色十字军{/link}和{link:nak}纳克{/link}萨玛斯。
• 她与{link:sylvanas-windrunner}希尔瓦娜斯{/link}和黑暗游侠克莉亚一起骑马前往{link:the-marris-stead}玛瑞斯农场{/link}，寻找{link:nathanos-blightcaller}纳萨诺斯·玛瑞斯{/link}。]=],
		},
		{
			title = "未载之事",
			text = [=[关于这段时期，没有任何编年史记载安雅如今在何处效力，也没有记载{link:garek-bandarion}加瑞克{/link}倒下之后她做了什么。]=],
		},
	},
	bonds = {
		{ id = "garek-bandarion", name = "加瑞克·班达里昂", note = "她的同伴" },
		{ id = "sylvanas-windrunner", name = "希尔瓦娜斯·风行者", note = "她的女王" },
	},
})

