			text = [=[达妮莎把{link:rudolph-gelhardt}盖尔哈特{/link}的首级送到了{link:undercity}幽暗城{/link}，向{link:sylvanas-windrunner}黑暗女王{/link}表明{link:tyr-s-watch}提尔守望{/link}能够整肃自己的门户。希尔瓦娜斯并不怀疑达妮莎的诚意。她说，她预计会有更多的圣骑士发疯，有朝一日她也许会决定不再容忍这个教团。她告诉教团的圣骑士们要好好效力，她会一直注视着他们。]=],
		},
	},
	mentions = {
